import { useState, useEffect } from "react";
import { getTransactions, deleteTransaction, createTransaction, updateTransaction } from "../services/api";
import { G } from "../App";

const EXPENSE_CATS = ["Food","Transport","Shopping","Health","Entertainment","Utilities","Education","Other"];
const INCOME_CATS  = ["Salary","Freelance","Business","Investment","Other"];
const fmt = n => `₹${Number(n || 0).toLocaleString("en-IN")}`;
const now = new Date();

export default function Transactions() {
  const [txns, setTxns]       = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab]         = useState("all"); // all | income | expense
  const [filter, setFilter]   = useState({ month: now.getMonth() + 1, year: now.getFullYear() });
  const [showAdd, setShowAdd] = useState(false);
  const [editTxn, setEditTxn] = useState(null);
  const [form, setForm]       = useState({ description: "", amount: "", category: "Food", type: "expense", date: now.toISOString().split("T")[0] });
  const [saving, setSaving]   = useState(false);
  const [msg, setMsg]         = useState("");

  const load = () => {
    setLoading(true);
    const params = { month: filter.month, year: filter.year };
    if (tab !== "all") params.type = tab;
    getTransactions(params).then(r => setTxns(r.data || [])).finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [filter, tab]);

  const del = async (id) => {
    if (!window.confirm("Delete this transaction?")) return;
    await deleteTransaction(id); load();
  };

  const startEdit = (t) => {
    setEditTxn(t);
    setForm({ description: t.description, amount: t.amount, category: t.category, type: t.type, date: t.date.split("T")[0] });
    setShowAdd(true);
    window.scrollTo(0, 0);
  };

  const save = async () => {
    if (!form.description || !form.amount) { setMsg("❌ Fill description and amount."); return; }
    setSaving(true);
    try {
      if (editTxn) {
        await updateTransaction(editTxn.id, { ...form, amount: parseFloat(form.amount), date: new Date(form.date).toISOString() });
        setMsg("✅ Updated!");
      } else {
        await createTransaction({ ...form, amount: parseFloat(form.amount), date: new Date(form.date).toISOString() });
        setMsg("✅ Added!");
      }
      setForm({ description: "", amount: "", category: "Food", type: "expense", date: now.toISOString().split("T")[0] });
      setShowAdd(false); setEditTxn(null); load();
      setTimeout(() => setMsg(""), 3000);
    } catch (e) { setMsg("❌ " + (e.response?.data?.detail || "Error")); }
    setSaving(false);
  };

  const cancel = () => { setShowAdd(false); setEditTxn(null); setMsg(""); setForm({ description: "", amount: "", category: "Food", type: "expense", date: now.toISOString().split("T")[0] }); };

  const filtered = txns;
  const totalIncome  = txns.filter(t => t.type === "income").reduce((s, t) => s + t.amount, 0);
  const totalExpense = txns.filter(t => t.type === "expense").reduce((s, t) => s + t.amount, 0);

  const s = {
    page: { animation: "fadeIn 0.3s ease" },
    heading: { fontSize: 26, fontWeight: 900, color: "#0f172a", letterSpacing: "-0.5px" },
    sub: { color: "#64748b", fontSize: 13, marginTop: 3, marginBottom: 24 },
    topRow: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20, flexWrap: "wrap", gap: 12 },
    summaryRow: { display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 14, marginBottom: 22 },
    sumCard: (color) => ({ background: "#fff", border: `1.5px solid ${color}30`, borderRadius: 14, padding: "16px 20px", borderTop: `4px solid ${color}` }),
    sumLabel: { fontSize: 11, color: "#64748b", fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", marginBottom: 6 },
    sumVal: (color) => ({ fontSize: 22, fontWeight: 900, color, fontFamily: G.mono }),
    tabs: { display: "flex", gap: 4, background: "#f0f4ff", borderRadius: 10, padding: 4, marginBottom: 18, width: "fit-content" },
    tab: (active) => ({ padding: "8px 20px", borderRadius: 8, border: "none", cursor: "pointer", fontFamily: G.font, fontWeight: 600, fontSize: 13, background: active ? "#2563eb" : "transparent", color: active ? "#fff" : "#64748b" }),
    filters: { display: "flex", gap: 10, marginBottom: 18, flexWrap: "wrap" },
    select: { background: "#f8faff", border: "1.5px solid #dbeafe", borderRadius: 8, padding: "8px 12px", color: "#0f172a", fontSize: 13, fontFamily: G.font },
    addBtn: { background: "linear-gradient(135deg, #2563eb, #1d4ed8)", border: "none", borderRadius: 10, padding: "10px 20px", color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font, boxShadow: "0 4px 14px rgba(37,99,235,0.25)" },
    formCard: { background: "#fff", border: "1.5px solid #dbeafe", borderRadius: 16, padding: 24, marginBottom: 20, boxShadow: "0 4px 20px rgba(37,99,235,0.08)" },
    formTitle: { fontSize: 16, fontWeight: 800, color: "#1e3a8a", marginBottom: 18 },
    label: { fontSize: 11, color: "#64748b", fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", marginBottom: 5, display: "block" },
    input: { background: "#f8faff", border: "1.5px solid #dbeafe", borderRadius: 10, padding: "10px 14px", color: "#0f172a", fontSize: 13, fontFamily: G.font, width: "100%" },
    row3: { display: "grid", gridTemplateColumns: "2fr 1fr 1fr", gap: 12, marginBottom: 12 },
    row2: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 14 },
    btnRow: { display: "flex", gap: 10 },
    saveBtn: { padding: "10px 24px", background: "linear-gradient(135deg, #2563eb, #1d4ed8)", border: "none", borderRadius: 10, color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font },
    cancelBtn: { padding: "10px 20px", background: "#f8faff", border: "1.5px solid #dbeafe", borderRadius: 10, color: "#64748b", fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: G.font },
    typeToggle: { display: "flex", gap: 8, marginBottom: 14 },
    typeBtn: (active, color) => ({ padding: "8px 18px", background: active ? color : "#f8faff", border: `2px solid ${color}`, borderRadius: 8, color: active ? "#fff" : color, fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font }),
    tableCard: { background: "#fff", border: "1.5px solid #dbeafe", borderRadius: 16, overflow: "hidden", boxShadow: "0 2px 12px rgba(37,99,235,0.06)" },
    th: { padding: "12px 16px", textAlign: "left", color: "#64748b", fontSize: 11, letterSpacing: 1.5, textTransform: "uppercase", fontWeight: 700, background: "#f8faff", borderBottom: "1.5px solid #dbeafe" },
    td: { padding: "14px 16px", borderBottom: "1px solid #f1f5f9", fontSize: 13, verticalAlign: "middle" },
    catBadge: { background: "#eff6ff", color: "#2563eb", border: "1px solid #bfdbfe", padding: "3px 10px", borderRadius: 20, fontSize: 11, fontWeight: 700 },
    incBadge: { background: "#f0fdf4", color: "#16a34a", border: "1px solid #bbf7d0", padding: "3px 10px", borderRadius: 20, fontSize: 11, fontWeight: 700 },
    expBadge: { background: "#fef2f2", color: "#dc2626", border: "1px solid #fecaca", padding: "3px 10px", borderRadius: 20, fontSize: 11, fontWeight: 700 },
    editBtn: { background: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: 6, color: "#2563eb", padding: "5px 12px", cursor: "pointer", fontSize: 12, fontFamily: G.font, fontWeight: 600, marginRight: 6 },
    delBtn: { background: "#fef2f2", border: "1px solid #fecaca", borderRadius: 6, color: "#dc2626", padding: "5px 12px", cursor: "pointer", fontSize: 12, fontFamily: G.font, fontWeight: 600 },
    msg: (ok) => ({ background: ok ? "#f0fdf4" : "#fef2f2", border: `1px solid ${ok ? "#bbf7d0" : "#fecaca"}`, borderRadius: 8, padding: "10px 14px", fontSize: 13, color: ok ? "#16a34a" : "#dc2626", marginBottom: 12 }),
  };

  const cats = form.type === "income" ? INCOME_CATS : EXPENSE_CATS;

  return (
    <div style={s.page}>
      <div style={s.topRow}>
        <div>
          <div style={s.heading}>Transactions</div>
          <div style={s.sub}>{filtered.length} records found</div>
        </div>
        <button style={s.addBtn} onClick={() => { if (showAdd && !editTxn) cancel(); else { setEditTxn(null); setShowAdd(true); } }}>
          {showAdd && !editTxn ? "✕ Cancel" : "+ Add Transaction"}
        </button>
      </div>

      {/* Summary Cards */}
      <div style={s.summaryRow}>
        <div style={s.sumCard("#16a34a")}>
          <div style={s.sumLabel}>Total Income</div>
          <div style={s.sumVal("#16a34a")}>{fmt(totalIncome)}</div>
        </div>
        <div style={s.sumCard("#dc2626")}>
          <div style={s.sumLabel}>Total Expenses</div>
          <div style={s.sumVal("#dc2626")}>{fmt(totalExpense)}</div>
        </div>
        <div style={s.sumCard("#2563eb")}>
          <div style={s.sumLabel}>Net Balance</div>
          <div style={s.sumVal(totalIncome - totalExpense >= 0 ? "#2563eb" : "#dc2626")}>{fmt(totalIncome - totalExpense)}</div>
        </div>
      </div>

      {/* Add / Edit Form */}
      {showAdd && (
        <div style={s.formCard}>
          <div style={s.formTitle}>{editTxn ? "✏️ Edit Transaction" : "➕ Add New Transaction"}</div>
          {msg && <div style={s.msg(msg.startsWith("✅"))}>{msg}</div>}
          <div style={s.typeToggle}>
            <button style={s.typeBtn(form.type === "expense", "#dc2626")} onClick={() => setForm(f => ({ ...f, type: "expense", category: "Food" }))}>💸 Expense</button>
            <button style={s.typeBtn(form.type === "income", "#16a34a")} onClick={() => setForm(f => ({ ...f, type: "income", category: "Salary" }))}>💰 Income</button>
          </div>
          <div style={s.row3}>
            <div>
              <label style={s.label}>Description</label>
              <input style={s.input} placeholder="e.g. Lunch, Rent, Salary..." value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} />
            </div>
            <div>
              <label style={s.label}>Amount (₹)</label>
              <input style={s.input} type="number" placeholder="0.00" value={form.amount} onChange={e => setForm(f => ({ ...f, amount: e.target.value }))} />
            </div>
            <div>
              <label style={s.label}>Date</label>
              <input style={s.input} type="date" value={form.date} onChange={e => setForm(f => ({ ...f, date: e.target.value }))} />
            </div>
          </div>
          <div style={{ marginBottom: 14 }}>
            <label style={s.label}>Category</label>
            <select style={{ ...s.input, width: "50%" }} value={form.category} onChange={e => setForm(f => ({ ...f, category: e.target.value }))}>
              {cats.map(c => <option key={c}>{c}</option>)}
            </select>
          </div>
          <div style={s.btnRow}>
            <button style={s.saveBtn} onClick={save} disabled={saving}>{saving ? "Saving..." : editTxn ? "Update Transaction" : "Add Transaction"}</button>
            <button style={s.cancelBtn} onClick={cancel}>Cancel</button>
          </div>
        </div>
      )}

      {/* Filters + Tabs */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12, marginBottom: 16 }}>
        <div style={s.tabs}>
          {["all","expense","income"].map(t => (
            <button key={t} style={s.tab(tab === t)} onClick={() => setTab(t)}>
              {t === "all" ? "All" : t === "expense" ? "💸 Expenses" : "💰 Income"}
            </button>
          ))}
        </div>
        <div style={s.filters}>
          <select style={s.select} value={filter.month} onChange={e => setFilter(f => ({ ...f, month: +e.target.value }))}>
            {[...Array(12)].map((_, i) => <option key={i+1} value={i+1}>{new Date(0,i).toLocaleString("en",{month:"long"})}</option>)}
          </select>
          <select style={s.select} value={filter.year} onChange={e => setFilter(f => ({ ...f, year: +e.target.value }))}>
            {[2023,2024,2025,2026].map(y => <option key={y}>{y}</option>)}
          </select>
        </div>
      </div>

      {/* Table */}
      <div style={s.tableCard}>
        {msg && !showAdd && <div style={{ padding: "0 16px 12px" }}><div style={s.msg(msg.startsWith("✅"))}>{msg}</div></div>}
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              {["Date","Description","Category","Type","Amount","Actions"].map(h => <th key={h} style={s.th}>{h}</th>)}
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={6} style={{ ...s.td, textAlign: "center", color: "#94a3b8", padding: "40px" }}>Loading...</td></tr>
            ) : filtered.length === 0 ? (
              <tr><td colSpan={6} style={{ ...s.td, textAlign: "center", color: "#94a3b8", padding: "40px" }}>No transactions found. Add one above!</td></tr>
            ) : filtered.map(t => (
              <tr key={t.id} style={{ transition: "background 0.15s" }} onMouseEnter={e => e.currentTarget.style.background="#f8faff"} onMouseLeave={e => e.currentTarget.style.background=""}>
                <td style={s.td}><span style={{ color: "#64748b", fontSize: 12 }}>{new Date(t.date).toLocaleDateString("en-IN")}</span></td>
                <td style={s.td}><span style={{ fontWeight: 600, color: "#0f172a" }}>{t.description}</span></td>
                <td style={s.td}><span style={s.catBadge}>{t.category}</span></td>
                <td style={s.td}><span style={t.type === "income" ? s.incBadge : s.expBadge}>{t.type}</span></td>
                <td style={s.td}><span style={{ fontFamily: G.mono, fontWeight: 800, fontSize: 14, color: t.type === "income" ? "#16a34a" : "#dc2626" }}>{t.type === "income" ? "+" : "-"}{fmt(t.amount)}</span></td>
                <td style={s.td}>
                  <button style={s.editBtn} onClick={() => startEdit(t)}>✏️ Edit</button>
                  <button style={s.delBtn} onClick={() => del(t.id)}>🗑️ Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
